test('lineDiscount with bulk discount at exactly 10 units', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  const total = lineTotal(line);
  const bulkDiscount = Math.round((total) * 2.5 / 100);
  assert.equal(discount, bulkDiscount);
});

test('lineDiscount with bulk discount at more than 10 units', () => {
  const line = { qty: 20, unitPrice: 5000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  const total = lineTotal(line);
  const bulkDiscount = Math.round(total * 2.5 / 100);
  assert.equal(discount, bulkDiscount);
});

test('lineDiscount no bulk discount with 9 units', () => {
  const line = { qty: 9, unitPrice: 10000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineDiscount bulk discount applied after regular discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 };
  const total = lineTotal(line);
  const regularDiscount = Math.round(total * 10 / 100);
  const amountAfterRegular = total - regularDiscount;
  const bulkDiscount = Math.round(amountAfterRegular * 2.5 / 100);
  const expectedTotal = regularDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), expectedTotal);
});

test('lineDiscount with tier discount and bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 5, vatRate: 21 };
  const total = lineTotal(line);
  const regularDiscount = Math.round(total * 5 / 100);
  const amountAfterRegular = total - regularDiscount;
  const bulkDiscount = Math.round(amountAfterRegular * 2.5 / 100);
  const expectedTotal = regularDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), expectedTotal);
});

