test('invoiceTotals with single line with discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  const regularDiscount = Math.round(100000 * 10 / 100);
  const bulkDiscount = Math.round((100000 - regularDiscount) * 2.5 / 100);
  const totalDiscount = regularDiscount + bulkDiscount;
  assert.equal(totals.discount, totalDiscount);
  const vat = Math.round((100000 - totalDiscount) * 21 / 100);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 100000 - totalDiscount + vat);
});

test('invoiceTotals with multiple lines with different discounts', () => {
  const invoice = {
    customerId: 'C-001',
