  const totals = invoiceTotals(invoice);
  const regularDiscount1 = Math.round(100000 * 10 / 100);
  const bulkDiscount1 = Math.round((100000 - regularDiscount1) * 2.5 / 100);
  const discount1 = regularDiscount1 + bulkDiscount1;
  const discount2 = Math.round(180000 * 5 / 100);
  const vat1 = Math.round((100000 - discount1) * 21 / 100);
  const vat2 = Math.round((180000 - discount2) * 21 / 100);
  assert.equal(totals.subtotal, 280000);
  assert.equal(totals.discount, discount1 + discount2);
  assert.equal(totals.vat, vat1 + vat2);
  assert.equal(totals.total, 280000 - (discount1 + discount2) + (vat1 + vat2));
});

