test('lineVat calculates VAT on amount after discount', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  const vat = lineVat(line);
  const total = 10000;
  const regularDiscount = Math.round(total * 10 / 100);
  const bulkDiscount = Math.round((total - regularDiscount) * 2.5 / 100);
  const amountAfterDiscount = total - regularDiscount - bulkDiscount;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(vat, expectedVat);
});

