  assert.equal(vat, Math.round(9500 * 21 / 100));
});

test('lineVat with 9% VAT rate', () => {
  const line = { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 };
  const vat = lineVat(line);
  const total = 3700;
  const bulkDiscount = Math.round(total * 2.5 / 100);
  const amountAfterDiscount = total - bulkDiscount;
  const expectedVat = Math.round(amountAfterDiscount * 9 / 100);
  assert.equal(vat, expectedVat);
});

